-- Payment Via NPHIES · Rafha — reconciliation SQL pack (READ-ONLY; run on the Rafha database, tables unqualified)
-- Verified objects (Rafha, Sep 2026): HS_NPHIES_PAYMENT_RECONCLATION (table), HS_NPHIES_PAYMENT_RECONC_DTL (table),
-- HS_NPHIES_CLAIM_REQUEST (table), RC_EPISODE_INVOICES (table), CUSTOMER_GROUPS (table).
-- HS_NPHIES_CLAIM_SOA_DATA and HS_NPHIES_CLAIM_SUMMARY are VIEWS; SOA_DATA = CLAIM_REQUEST x RC_EPISODE_INVOICES x RC_PATIENT_EPISODES
-- and SUMMARY is item-level and times out (>60 s) — so the pack joins the base tables instead.

-- 1) Discovery: payers, counts, date range, named vs no customer group
SELECT p.INSURER_ID, MAX(p.INSURER_NAME) INAME, COUNT(*) N, SUM(CASE WHEN p.PAYMENT_AMOUNT>0 THEN 1 ELSE 0 END) NPOS,
       ROUND(SUM(CASE WHEN p.PAYMENT_AMOUNT>0 THEN p.PAYMENT_AMOUNT END),2) AMT,
       TO_CHAR(MIN(p.PAYMENT_DATE),'YYYY-MM-DD') D0, TO_CHAR(MAX(p.PAYMENT_DATE),'YYYY-MM-DD') D1,
       (SELECT MAX(g.CUSTOMER_GROUP_NO||' '||g.DESCRIPTION_S) FROM CUSTOMER_GROUPS g WHERE g.NPHIES_ID=p.INSURER_ID) GRP
FROM HS_NPHIES_PAYMENT_RECONCLATION p GROUP BY p.INSURER_ID ORDER BY AMT DESC NULLS LAST;

-- 2) Who issued the notice when the licence has no group (GlobeMed etc.): paymentIssuer in JSON_MSG
SELECT x.INSURER_ID, DBMS_LOB.SUBSTR(p.JSON_MSG, 200, DBMS_LOB.INSTR(p.JSON_MSG, 'paymentIssuer')) ISSUER
FROM (SELECT INSURER_ID, MAX(PAYMENT_PK) PK FROM HS_NPHIES_PAYMENT_RECONCLATION GROUP BY INSURER_ID) x
JOIN HS_NPHIES_PAYMENT_RECONCLATION p ON p.PAYMENT_PK=x.PK;

-- 3) Per-payment reconciliation, packed 25 notices per row (MCP 200-row cap). Fields per notice:
--    pk | header date / first claim-line date | insurer | amount | header fee | Σ line amount / Σ line early-fee | lines | linked
--    | claimed company net (incl. VAT) | VAT | claim send month min/max | booking account(s) | service month:lines:amount;...
--    Claim link: CLAIM_REQUEST.REQUEST_PREAUTH_ID = SUBSTR(dtl.REQUEST_PREAUTH_ID, INSTR(dtl.REQUEST_PREAUTH_ID,'_')+1)
--    Run twice: {FILTER} = p.INSURER_ID='7000911508'  and  p.INSURER_ID<>'7000911508'
SELECT 'NPB'||FLOOR((RN-1)/25) B, LISTAGG(S, '~') WITHIN GROUP (ORDER BY RN) X FROM (SELECT ROW_NUMBER() OVER (ORDER BY PK) RN, PK||'|'||PD||'/'||DD||'|'||INS||'|'||PAMT||'|'||FEE||'|'||DSUM||'/'||DFEE||'|'||DCNT||'|'||LNK||'|'||CLM||'|'||TAX||'|'||SND||'|'||ACCS||'|'||MONS S FROM (SELECT q.PK, q.PD, MIN(q.DD) DD, q.INS, q.PAMT, q.FEE, SUM(q.DAMT) DSUM, SUM(q.DFEE) DFEE, SUM(q.DCNT) DCNT, SUM(q.LNK) LNK, SUM(q.CLM) CLM, SUM(q.TAX) TAX, MIN(q.SND1)||'/'||MAX(q.SND2) SND, LISTAGG(CASE WHEN q.SM IS NOT NULL THEN q.SM||':'||q.DCNT||':'||q.DAMT END, ';') WITHIN GROUP (ORDER BY q.SM) MONS, MAX(q.ACCS) ACCS FROM (SELECT p.PAYMENT_PK PK, TO_CHAR(p.PAYMENT_DATE,'YYYY-MM-DD') PD, MIN(TO_CHAR(d.PAYMENT_DATE,'YYYY-MM-DD')) DD, p.INSURER_ID INS, p.PAYMENT_AMOUNT PAMT, NVL(p.EARLY_FEE_AMOUNT,0) FEE, TO_CHAR(ei.INVOICE_START_DATE,'YYYY-MM') SM, ROUND(SUM(d.PAYMENT_AMOUNT),2) DAMT, ROUND(SUM(NVL(d.EARLY_FEE_AMOUNT,0)),2) DFEE, COUNT(d.PAYMENT_PK) DCNT, COUNT(ei.INVOICE_NO) LNK, ROUND(SUM(nc.NET),2) CLM, ROUND(SUM(nc.TAX),2) TAX, MIN(TO_CHAR(nc.SD,'YYYY-MM')) SND1, MAX(TO_CHAR(nc.SD,'YYYY-MM')) SND2, MIN(ei.ACCOUNT_NO)||CASE WHEN MIN(ei.ACCOUNT_NO)<>MAX(ei.ACCOUNT_NO) THEN ','||MAX(ei.ACCOUNT_NO) END ACCS FROM HS_NPHIES_PAYMENT_RECONCLATION p LEFT JOIN HS_NPHIES_PAYMENT_RECONC_DTL d ON d.PAYMENT_PK=p.PAYMENT_PK LEFT JOIN (SELECT REQUEST_PREAUTH_ID RID, MIN(EPISODE_INVOICE_NO) INV, MIN(CREATION_DATE) SD, MAX(TOTAL_COMPANY_NET_AMOUNT) NET, MAX(TOTAL_COMPANY_TAX_AMOUNNT) TAX FROM HS_NPHIES_CLAIM_REQUEST WHERE REQUEST_PREAUTH_ID IS NOT NULL GROUP BY REQUEST_PREAUTH_ID) nc ON nc.RID = SUBSTR(d.REQUEST_PREAUTH_ID, INSTR(d.REQUEST_PREAUTH_ID,'_')+1) LEFT JOIN RC_EPISODE_INVOICES ei ON ei.INVOICE_NO = nc.INV WHERE p.PAYMENT_AMOUNT>0 AND {FILTER} GROUP BY p.PAYMENT_PK, p.PAYMENT_DATE, p.INSURER_ID, p.PAYMENT_AMOUNT, p.EARLY_FEE_AMOUNT, TO_CHAR(ei.INVOICE_START_DATE,'YYYY-MM')) q GROUP BY q.PK, q.PD, q.INS, q.PAMT, q.FEE)) GROUP BY FLOOR((RN-1)/25) ORDER BY 1


-- 4) Payer's own period wording
SELECT PAYMENT_PK, SUBSTR(DISPOSITION,1,60) DISP FROM HS_NPHIES_PAYMENT_RECONCLATION WHERE PAYMENT_AMOUNT>0 AND DISPOSITION IS NOT NULL;

-- 5) Ledger side: Rafha receipts credited to 1240007 (BR / JV, posted + open)
SELECT VOUCHER_NO, TO_CHAR(MIN(VM_DATE),'YYYY-MM-DD') DT, MIN(SUB_ACCOUNT_NO) SUB, ROUND(SUM(CR_AMOUNT-DR_AMOUNT),2) AMT, MIN(STATUS) ST
FROM GL_TRANSACTIONS_DETAILS WHERE ACCOUNT_NO='1240007' AND STATUS<>'C' AND VM_DATE>=DATE '2025-01-01' AND SUB_SYSTEM_CODE IN ('CM','GL')
  AND (VOUCHER_NO LIKE 'BR%' OR VOUCHER_NO LIKE 'JV%') GROUP BY VOUCHER_NO, SUB_ACCOUNT_NO HAVING SUM(CR_AMOUNT-DR_AMOUNT)>0;

-- 6) Booking account names: GL sub-accounts of 1240007 ; CUSTOMER_GROUPS for NPHIES_ID
SELECT SUB_ACCOUNT_NO, MAX(SUB_ACCOUNT_ARB_NAME) NM FROM GL_TRANSACTIONS_DETAILS WHERE ACCOUNT_NO IN ('1240007','1240001') AND SUB_ACCOUNT_NO IS NOT NULL GROUP BY SUB_ACCOUNT_NO;
SELECT CUSTOMER_GROUP_NO, DESCRIPTION_S, DESCRIPTION_P, NPHIES_ID FROM CUSTOMER_GROUPS ORDER BY 1;
